    "2026-01-01T12:05:00.0000001Z", "outside", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "ties", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "ties", dynamic("alice"), "match",
    "2026-01-01T12:01:00Z", "ties", dynamic("alice"), "match",
    "2026-01-01T12:00:00Z", "overlap", dynamic("alice"), "match",
